using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.Controls;using UnityEngine.InputSystem.LowLevel;using UnityEngine.InputSystem.XR;using UnityEngine.XR;using UnityEngine.XR.OpenXR.Features.Interactions;using UnityEngine.XR.Interaction.Toolkit.Inputs.Simulation;
namespace VRMaintenanceResearch.HandsLabQuest3.Editor {
public static partial class HandsLabEditor {
static UnityEngine.InputSystem.InputDevice simLeft,simRight;static XRSimulatedHMD simHead;static Vector3 leftPosition=new Vector3(-.20f,1.15f,.45f),rightPosition=new Vector3(.20f,1.15f,.45f);static Quaternion leftRotation=Quaternion.identity,rightRotation=Quaternion.identity;static float leftGrip,rightGrip,leftTrigger,rightTrigger;static bool leftThumbTouch,rightThumbTouch;static bool simTracking=true;static double nextSim;static bool simRunning;
static partial void SimulatorCommand(string command){if(command=="sim_devices")Write("sim_device_inventory",InputSystem.devices.Select(d=>new{d.name,d.layout,d.deviceId,d.native}));else if(command=="sim_cleanup")SimCleanup();else if(command=="sim_start")SimStart();else if(command=="sim_stop")SimStop();else if(command=="sim_fist"){leftGrip=rightGrip=1;leftTrigger=rightTrigger=1;}else if(command=="sim_open"){leftGrip=rightGrip=0;leftTrigger=rightTrigger=0;}else if(command=="sim_point"){leftGrip=rightGrip=1;leftTrigger=rightTrigger=0;}else if(command=="sim_loss")simTracking=false;else if(command=="sim_recover")simTracking=true;else if(command=="sim_capture")CaptureGame("simulated_hands_"+DateTime.UtcNow.ToString("HHmmss"));else TestCommand(command);}
static partial void TestCommand(string command);
static void SimStart(){if(!EditorApplication.isPlaying)throw new Exception("Enter Play Mode first");if(!Lab||UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!=ScenePath)throw new Exception("Open HandsLab scene first");if(simRunning)throw new Exception("Simulation already active");if(InputSystem.devices.Any(d=>d is UnityEngine.InputSystem.XR.XRController||d is XRHMD))throw new Exception("XR input devices already present; preserve device ownership");InputSystem.RegisterLayout(@"{""name"":""HandsLabSimulatedTouch"",""extend"":""XRController"",""format"":""HLTC"",""controls"":[
{""name"":""primaryButton"",""layout"":""Button"",""offset"":0,""bit"":0},{""name"":""primaryTouched"",""layout"":""Button"",""offset"":0,""bit"":1},
{""name"":""secondaryButton"",""layout"":""Button"",""offset"":0,""bit"":2},{""name"":""secondaryTouched"",""layout"":""Button"",""offset"":0,""bit"":3},
{""name"":""gripPressed"",""layout"":""Button"",""offset"":0,""bit"":4},{""name"":""triggerPressed"",""layout"":""Button"",""offset"":0,""bit"":5},
{""name"":""triggerTouched"",""layout"":""Button"",""offset"":0,""bit"":6},{""name"":""thumbstickClicked"",""layout"":""Button"",""offset"":0,""bit"":7},
{""name"":""thumbstickTouched"",""layout"":""Button"",""offset"":1,""bit"":0},{""name"":""thumbrestTouched"",""layout"":""Button"",""offset"":1,""bit"":1},{""name"":""menu"",""layout"":""Button"",""offset"":1,""bit"":2},
{""name"":""thumbstick"",""layout"":""Vector2"",""offset"":4},{""name"":""grip"",""layout"":""Axis"",""offset"":12},{""name"":""trigger"",""layout"":""Axis"",""offset"":16},
{""name"":""devicePose"",""layout"":""Pose"",""offset"":32},{""name"":""pointer"",""layout"":""Pose"",""offset"":96},
{""name"":""isTracked"",""useStateFrom"":""devicePose/isTracked""},{""name"":""trackingState"",""useStateFrom"":""devicePose/trackingState""},
{""name"":""devicePosition"",""useStateFrom"":""devicePose/position""},{""name"":""deviceRotation"",""useStateFrom"":""devicePose/rotation""}]}" );simLeft=InputSystem.AddDevice("HandsLabSimulatedTouch","HandsLabSimulatedLeft");simRight=InputSystem.AddDevice("HandsLabSimulatedTouch","HandsLabSimulatedRight");InputSystem.SetDeviceUsage(simLeft,UnityEngine.InputSystem.CommonUsages.LeftHand);InputSystem.SetDeviceUsage(simRight,UnityEngine.InputSystem.CommonUsages.RightHand);simHead=(XRSimulatedHMD)InputSystem.AddDevice("XRSimulatedHMD","HandsLabSimulatedHMD");AssemblyReloadEvents.beforeAssemblyReload+=SimStop;simRunning=true;simTracking=true;leftThumbTouch=rightThumbTouch=false;leftGrip=rightGrip=leftTrigger=rightTrigger=0;EditorApplication.update+=SimTick;EditorApplication.playModeStateChanged+=SimPlayState;SimTick();Write("sim_devices",InputSystem.devices.Select(d=>new{d.name,d.layout,controls=d.allControls.Select(c=>c.name).ToArray()}));}
static void SimPlayState(PlayModeStateChange s){if(s==PlayModeStateChange.ExitingPlayMode)SimStop();}
static void SimCleanup(){if(EditorApplication.isPlaying)throw new Exception("Cleanup requires Edit Mode");var own=InputSystem.devices.Where(d=>!d.native&&(d.name.StartsWith("HandsLabSimulated")||d.layout=="HandsLabSimulatedTouch"||d.name=="XRSimulatedHMD")).ToArray();Write("sim_stale_fixture_cleanup",own.Select(d=>new{d.name,d.layout,d.deviceId}));foreach(var d in own)InputSystem.RemoveDevice(d);}
static void SimStop(){AssemblyReloadEvents.beforeAssemblyReload-=SimStop;EditorApplication.update-=SimTick;EditorApplication.playModeStateChanged-=SimPlayState;simRunning=false;if(simLeft!=null&&simLeft.added)InputSystem.RemoveDevice(simLeft);if(simRight!=null&&simRight.added)InputSystem.RemoveDevice(simRight);if(simHead!=null&&simHead.added)InputSystem.RemoveDevice(simHead);simLeft=null;simRight=null;simHead=null;}
static void SimTick(){if(!simRunning||!EditorApplication.isPlaying)return;double now=EditorApplication.timeSinceStartup;if(now<nextSim)return;nextSim=now+1d/60;var space=UnityEngine.Object.FindFirstObjectByType<Runtime.HandsLabSession>().trackingSpace;var pos=space.InverseTransformPoint(new Vector3(0,1.55f,0));InputSystem.QueueStateEvent(simHead,new XRSimulatedHMDState{isTracked=true,trackingState=3,devicePosition=pos,deviceRotation=Quaternion.Euler(30,0,0),centerEyePosition=pos,centerEyeRotation=Quaternion.Euler(30,0,0),leftEyePosition=pos+Vector3.left*.032f,rightEyePosition=pos+Vector3.right*.032f,leftEyeRotation=Quaternion.Euler(30,0,0),rightEyeRotation=Quaternion.Euler(30,0,0)});QueueTouch(simLeft,space.InverseTransformPoint(leftPosition),Quaternion.Inverse(space.rotation)*leftRotation,leftGrip,leftTrigger,leftThumbTouch);QueueTouch(simRight,space.InverseTransformPoint(rightPosition),Quaternion.Inverse(space.rotation)*rightRotation,rightGrip,rightTrigger,rightThumbTouch);}
static void QueueTouch(UnityEngine.InputSystem.InputDevice d,Vector3 pos,Quaternion rot,float grip,float trigger,bool thumbTouch){using(StateEvent.From(d,out var ev)){foreach(string path in new[]{"devicePose","pointer"}){var p=d.GetChildControl<PoseControl>(path);p.isTracked.WriteValueIntoEvent(simTracking?1f:0f,ev);p.trackingState.WriteValueIntoEvent(simTracking?3:0,ev);p.position.WriteValueIntoEvent(pos,ev);p.rotation.WriteValueIntoEvent(rot,ev);}d.GetChildControl<AxisControl>("grip").WriteValueIntoEvent(grip,ev);d.GetChildControl<AxisControl>("trigger").WriteValueIntoEvent(trigger,ev);d.GetChildControl<ButtonControl>("gripPressed").WriteValueIntoEvent(grip>.7f?1f:0f,ev);d.GetChildControl<ButtonControl>("triggerPressed").WriteValueIntoEvent(trigger>.7f?1f:0f,ev);d.GetChildControl<ButtonControl>("primaryTouched").WriteValueIntoEvent(thumbTouch?1f:0f,ev);InputSystem.QueueEvent(ev);}}
static void CaptureGame(string filename,Camera cameraOverride=null){var camera=cameraOverride?cameraOverride:Camera.main;if(!camera)throw new Exception("Main Camera missing");var rt=new RenderTexture(1600,1000,24);var old=camera.targetTexture;var active=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(Out+"/"+filename+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{camera.targetTexture=old;RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(rt);}}
}}
